script.script:
import hudson.model.*
import groovy.json.JsonSlurper

// Hardened scheduling: avoid null/empty values that can break Jenkins internals.
def run = (binding.hasVariable('build') ? build : Thread.currentThread().executable)
def env = run?.getEnvironment(listener)
def workspace = env?.WORKSPACE
if (!workspace) {
  println "WORKSPACE env var not found; skipping triggers"
  return
}

def reportFile = new File(workspace + "/instance-processing-report.json")
if (!reportFile.exists()) {
  println "No instance-processing-report.json found; skipping triggers"
  return
}

def report = new JsonSlurper().parse(reportFile)
def results = report?.results
if (!(results instanceof List)) {
  println "instance-processing-report.json has no results list; skipping triggers"
  return
}

def getJobOrFail = { name ->
  def job = Hudson.instance.getJob(name)
  if (job == null) {
    throw new IllegalStateException("Job '" + name + "' was not found")
  }
  return job
}

def causeAction = new CauseAction(new Cause.UpstreamCause(run))
def scheduled = 0

def schedule = { jobName, params, uuid, action ->
  Hudson.instance.queue.schedule(getJobOrFail(jobName), 0, causeAction, new ParametersAction(params))
  println "Scheduled " + jobName + " (" + action + ") for " + uuid
  scheduled++
}

results.each { result ->
  def action = result?.action == null ? "" : result.action.toString()
  def uuidVal = result?.instanceUuid
  def uuid = (uuidVal == null) ? "" : uuidVal.toString().trim()

  if (!action || !uuid) {
    return
  }

  switch (action) {
    case "destroy":
    case "reset":
      // Must mirror getGitOpsProtectedEnvironments() in node-scripts/src/utils/config.js
      if (result?.environment in ["prod"]) {
        println "Refusing '" + action + "' for " + uuid + " in protected environment '" + result.environment + "'"
        return
      }
      schedule("destroy-instance", [
        new StringParameterValue("instanceUuid", uuid),
        new BooleanParameterValue("recreate", action == "reset")
      ], uuid, action)
      break
    case "create":
    case "update":
    case "redeploy":
      schedule("pipeline3", [
        new StringParameterValue("instanceUuid", uuid),
        new BooleanParameterValue("creation", action == "create"),
        new BooleanParameterValue("artifactsChanges", result.artifactsChanges == true),
        new BooleanParameterValue("deploymentChanges", result.deploymentChanges == true),
        new BooleanParameterValue("propertiesChanges", result.propertiesChanges == true),
        new BooleanParameterValue("dataChanges", result.dataChanges == true),
        new BooleanParameterValue("instanceActive", true)
      ], uuid, action)
      break
    default:
      println "Unknown action '" + action + "' for " + uuid + "; skipping"
  }
}

println "Scheduled " + scheduled + " job(s)"
